INTERLIS 2.3; MODEL F AT "https://example.org" VERSION "1" = TOPIC T = DOMAIN Base = (red, green, blue) ORDERED;
More EXTENDS Base = (red(dark, light: FINAL), yellow); Last EXTENDS More = (blue(pale)); CLASS A = value: Base; END A;
CLASS B = value: Last; EXISTENCE CONSTRAINT value REQUIRED IN A:value; END B; END T; END F.

INTERLIS 2.3; MODEL F AT "https://example.org" VERSION "1" = TOPIC T = STRUCTURE S = number: 0..99; END S; DOMAIN Code = FORMAT BASED ON S (number/2);
STRUCTURE Container = nested: S; extra: 0..9; END Container;
DOMAIN Pair = FORMAT BASED ON Container (nested/Code "-" extra);
STRUCTURE Extended EXTENDS S = suffix: 0..9; END Extended;
DOMAIN ExtendedCode EXTENDS Code = FORMAT BASED ON Extended (INHERITANCE "-" suffix); END T; END F.

